COLORS={"window":"#0A1216","sidebar":"#0C141B","panel":"#141D26","input":"#1B2732","header":"#12202A","border":"#2B3D4B","primary":"#D60B25","primary_hover":"#FF3652","text":"#F3F5F7","secondary":"#ADBECD","queued":"#073454","cyan":"#47BAFF","online":"#00D880"}
STYLESHEET=f"""*{{font-family:'Segoe UI';font-size:13px;color:{COLORS['text']};}} QWidget#Root,QWidget#Workspace,QWidget#WorkspaceViewport,QScrollArea#WorkspaceScroll{{background:{COLORS['window']};}} QWidget#TitleBar,QWidget#Sidebar{{background:{COLORS['sidebar']};}} QWidget#GeminiPanel{{background:#0E171E;border-left:1px solid {COLORS['border']};}} QFrame#Panel,QGroupBox{{background:{COLORS['panel']};border:1px solid {COLORS['border']};border-radius:8px;}} QLineEdit,QTextEdit,QComboBox,QSpinBox{{background:{COLORS['input']};border:1px solid {COLORS['border']};border-radius:7px;padding:7px;}} QPushButton{{background:#1A2730;border:1px solid {COLORS['border']};border-radius:7px;padding:7px 12px;}} QPushButton:hover{{background:#223541;}} QPushButton#Primary{{background:{COLORS['primary']};border-color:{COLORS['primary']};font-weight:600;}} QPushButton#Primary:hover{{background:{COLORS['primary_hover']};}} QPushButton#Nav{{text-align:left;border:none;padding:10px 14px;background:transparent;}} QPushButton#Nav:checked{{background:#42131C;border-left:3px solid #FF1437;border-radius:0;font-weight:600;}} QLabel#Muted{{color:{COLORS['secondary']};}} QLabel#Heading{{font-size:16px;font-weight:600;}} QHeaderView::section{{background:{COLORS['header']};color:{COLORS['secondary']};border:none;border-bottom:1px solid {COLORS['border']};padding:8px;}} QTableView{{background:#101920;alternate-background-color:#111C24;border:1px solid {COLORS['border']};border-radius:7px;gridline-color:#1D2B35;selection-background-color:#173248;}} QProgressBar{{background:#202C34;border:0;border-radius:3px;height:6px;text-align:center;}} QProgressBar::chunk{{background:{COLORS['primary']};border-radius:3px;}} QScrollArea{{border:none;}}"""
